import os
from datetime import datetime, timedelta
from datadog_api_client import ApiClient, Configuration
from datadog_api_client.v2.api.metrics_api import MetricsApi
from datadog_api_client.v2.model.metrics_query_response import MetricsQueryResponse

def compare_metrics(metric_name: str, resource1_filter: str, resource2_filter: str, hours_back: int = 1):
    """
    Compare metric values for two resources using Datadog's Metrics API.

    Args:
        metric_name: The name of the metric to query (e.g., "system.cpu.user")
        resource1_filter: Filter for the first resource (e.g., "host:web-server-1")
        resource2_filter: Filter for the second resource (e.g., "host:web-server-2")
        hours_back: How many hours back to query (default: 1)

    Returns:
        dict: Comparison results with metric values for both resources
    """
    configuration = Configuration()
    configuration.api_key["apiKeyAuth"] = os.getenv("DD_API_KEY")
    configuration.api_key["appKeyAuth"] = os.getenv("DD_APP_KEY")

    end_time = datetime.utcnow()
    start_time = end_time - timedelta(hours=hours_back)

    with ApiClient(configuration) as api_client:
        metrics_api = MetricsApi(api_client)

        # Query for resource 1
        query1 = f"{metric_name}{{*{resource1_filter}*}}"
        response1: MetricsQueryResponse = metrics_api.query_metrics(
            body={
                "data": {
                    "attributes": {
                        "from": int(start_time.timestamp()),
                        "to": int(end_time.timestamp()),
                        "query": query1,
                    },
                    "type": "timeseries_request",
                }
            }
        )

        # Query for resource 2
        query2 = f"{metric_name}{{*{resource2_filter}*}}"
        response2: MetricsQueryResponse = metrics_api.query_metrics(
            body={
                "data": {
                    "attributes": {
                        "from": int(start_time.timestamp()),
                        "to": int(end_time.timestamp()),
                        "query": query2,
                    },
                    "type": "timeseries_request",
                }
            }
        )

        # Process results
        def process_series(series):
            if not series or not series[0].points:
                return None
            return sum(float(point.value) for point in series[0].points) / len(series[0].points)

        value1 = process_series(response1.data.series)
        value2 = process_series(response2.data.series)

        return {
            "metric": metric_name,
            "resource1": {
                "filter": resource1_filter,
                "average_value": value1,
            },
            "resource2": {
                "filter": resource2_filter,
                "average_value": value2,
            },
            "comparison": {
                "difference": value1 - value2 if value1 and value2 else None,
                "percentage_difference": ((value1 - value2) / value2 * 100) if value1 and value2 and value2 != 0 else None,
            },
            "time_window": {
                "start": start_time.isoformat(),
                "end": end_time.isoformat(),
            },
        }
